func _goml_m_gomlc_p_stdlib_p_bytes__source() string {
    var retv12272 string
    var source__2 string = "package bytes;\n\npub struct Bytes {\n    pub values: Vec[uint8],\n}\n\nimpl Bytes {\n    pub fn new() -> Bytes {\n        Bytes { values: Vec::new() }\n    }\n\n    pub fn with_capacity(capacity: int) -> Bytes {\n        Bytes {\n            values: Vec::with_capacity(capacity),\n        }\n    }\n\n    pub fn from_vec(values: Vec[uint8]) -> Bytes {\n        Bytes { values }\n    }\n\n    pub fn from_string(value: string) -> Bytes {\n        Bytes {\n            values: value.to_bytes(),\n        }\n    }\n\n    pub fn len(self: Bytes) -> int {\n        self.values.len()\n    }\n\n    pub fn capacity(self: Bytes) -> int {\n        self.values.capacity()\n    }\n\n    pub fn is_empty(self: Bytes) -> bool {\n        self.values.is_empty()\n    }\n\n    pub fn get(self: Bytes, index: int) -> uint8 {\n        self.values.get(index)\n    }\n\n    pub fn set(self: Bytes, index: int, value: uint8) -> unit {\n        self.values.set(index, value)\n    }\n\n    pub fn push(self: Bytes, value: uint8) -> unit {\n        self.values.push(value)\n    }\n\n    pub fn pop(self: Bytes) -> Option[uint8] {\n        self.values.pop()\n    }\n\n    pub fn reserve(self: Bytes, additional: int) -> unit {\n        self.values.reserve(additional)\n    }\n\n    pub fn truncate(self: Bytes, len: int) -> unit {\n        self.values.truncate(len)\n    }\n\n    pub fn clear(self: Bytes) -> unit {\n        self.values.clear()\n    }\n\n    pub fn slice(self: Bytes, start: int, end: int) -> Slice[uint8] {\n        self.values.slice(start, end)\n    }\n\n    pub fn to_vec(self: Bytes) -> Vec[uint8] {\n        self.values\n    }\n\n    pub fn to_string(self: Bytes) -> Result[string, string] {\n        let (valid, value) = string_from_utf8(self.values);\n        if valid {\n            Result::Ok(value)\n        } else {\n            Result::Err(\"invalid UTF-8\")\n        }\n    }\n}"
    retv12272 = source__2
    return retv12272
}

